const r = await tools.grill_confirm({
  requirements: `目标：调研「国内想买买不到、可以从海外买回来卖给中国人」的反向代购/海淘机会，给出具体品类清单+可行性分析。

范围：
1. 梳理"国内买不到/买不对/买着贵"的海外商品品类（数字商品、实体商品、订阅服务三大类）
2. 每个品类标注：需求证据、差价空间、合规风险
3. 明确红线：不做违规品类（仿牌、处方药、象牙制品等）

约束：基于已有调研能力（curl+代理实测、搜狗微信查需求证据），用户位置/规模待确认，先按"人在国内+小规模起步"最通用假设分析，用户回复后再细化。

验收标准：产出一份反向代购品类分析报告（含需求证据+差价+风险三列），提交推送GitHub。`,
  preferences_learned: []
});
return r;
